const (
	defaultProofTimeout = 60 * time.Second
	defaultProofPoll    = time.Second
	defaultNoCallDwell  = 10 * time.Second
	maxExpiryWait       = 90 * time.Second
)

// ApprovalFixture binds a live qualification scenario to one pre-provisioned,
// centrally signed approval. Request IDs are operator-created idempotency
// identifiers, never generated by the driver after the fixture is loaded.
type ApprovalFixture struct {
	ApprovalID      string `json:"approval_id"`
	ActionID        string `json:"action_id,omitempty"`
	Capability      string `json:"capability"`
	DecisionRequest string `json:"decision_request_id,omitempty"`
	ReplayRequest   string `json:"replay_request_id,omitempty"`
}

// SessionStimulus creates one fresh, private, single-resource session and sends
// one exact user message through Astronomer's existing authenticated product
// API. Stable client IDs make every mutation idempotent and auditable.
type SessionStimulus struct {
	ClientSessionID string `json:"client_session_id"`
	ClientMessageID string `json:"client_message_id"`
	AbortRequestID  string `json:"abort_request_id"`
	Intent          string `json:"intent"`
	ResourceType    string `json:"resource_type"`
	ResourceID      string `json:"resource_id"`
	Message         string `json:"message"`
}

// ActionFixture binds the exact capability expected after the fresh-session
// stimulus. The action ID is discovered only from the SSE event bound to the
// message receipt's exact turn; Charlie action IDs cannot be known before a
// real engine turn exists.
type ActionFixture struct {
	Capability string          `json:"capability"`
	Stimulus   SessionStimulus `json:"stimulus"`
}

// EventActionFixture binds unattended automation to a product event. The
// service session is created by the trigger dispatcher; no browser identity
// creates the session or sends an instruction.
type EventActionFixture struct {
	Capability     string `json:"capability"`
	TaskID         string `json:"task_id"`
	AbortRequestID string `json:"abort_request_id"`
}

type PendingApprovalFixture struct {
	Capability string          `json:"capability"`
	Stimulus   SessionStimulus `json:"stimulus"`
}

// VersionedRAGFixture proves one real route invocation against a uniquely
// identifiable corrected document revision. Markers are non-secret canaries
// that the operator placed in the selected product-version documentation.
type VersionedRAGFixture struct {
	Stimulus                SessionStimulus `json:"stimulus"`
	CorrectedRevisionMarker string          `json:"corrected_revision_marker"`
	ProductVersionMarker    string          `json:"product_version_marker"`
	CitationID              string          `json:"citation_id"`
	CitationTitle           string          `json:"citation_title"`
	CitationSource          string          `json:"citation_source"`
}

// GeneralAnswerFixture proves that the same product route can answer a
// non-product question without inventing a citation when retrieval finds no
// applicable product material.
type GeneralAnswerFixture struct {
	Stimulus             SessionStimulus `json:"stimulus"`
	ExpectedAnswerMarker string          `json:"expected_answer_marker"`
}

// AlertDeliveryFixture binds an alert scenario to one real, already-created
// Astronomer finding and delivery. It contains no notification content.
type AlertDeliveryFixture struct {
	FindingID             string `json:"finding_id"`
	DeliveryID            string `json:"delivery_id"`
	ExpectedBlockCode     string `json:"expected_block_code"`
	ExpectedWorkflowState string `json:"expected_workflow_state"`
}

// LiveFixtures is intentionally scenario-specific. Reusing one unconstrained
// identifier across scenarios could allow an earlier side effect to masquerade
// as proof for a later scenario.
type LiveFixtures struct {
	ApprovalExpiry          ApprovalFixture        `json:"approval_expiry"`
	ApprovalOnce            ApprovalFixture        `json:"approval_once"`
	ApprovalReject          ApprovalFixture        `json:"approval_reject"`
	AutoAllowlistedSuccess  EventActionFixture     `json:"auto_allowlisted_success"`
	AutoNonallowlisted      PendingApprovalFixture `json:"auto_nonallowlisted_approval"`
	LeaderKillFailover      ActionFixture          `json:"leader_kill_failover"`
	VersionedRAGGrounded    VersionedRAGFixture    `json:"versioned_rag_grounded"`
	GeneralAnswer           GeneralAnswerFixture   `json:"general_answer"`
	DiagnosisAlert          AlertDeliveryFixture   `json:"diagnosis_alert"`
	ApprovalPendingAlert    AlertDeliveryFixture   `json:"approval_pending_alert"`
	ApprovalRejectedAlert   AlertDeliveryFixture   `json:"approval_rejected_alert"`
	ApprovalExpiredAlert    AlertDeliveryFixture   `json:"approval_expired_alert"`
	BlockedAutoAlert        AlertDeliveryFixture   `json:"blocked_auto_alert"`
	FailedPreconditionAlert AlertDeliveryFixture   `json:"failed_precondition_alert"`
	FailedVerificationAlert AlertDeliveryFixture   `json:"failed_verification_alert"`
}

type LiveConfig struct {
	AstronomerURL         string
	AdminToken            string
	ApproverToken         string
	DeniedToken           string
	MetricSources         []MetricSource
	CounterMetrics        map[string]string
	Fixtures              LiveFixtures
	AllowHTTP             bool
	HTTPClient            *http.Client
	AgentScaler           AgentScaler
	IsolationObserver     IsolationObserver
	LeaderFailover        *KubernetesLeaderFailoverTarget
	EventStimulus         EventStimulus
	InfrastructureCommand string
	ProofTimeout          time.Duration
	ProofPoll             time.Duration
	NoCallDwell           time.Duration
}

// MetricSource binds one scrape endpoint to only its own optional bearer.
// Charlie central's qualification credential must never be forwarded to an
// Astronomer metrics listener (or vice versa).
type MetricSource struct {
	URL   string
	Token string
}

type metricEndpoint struct {
	url   *url.URL
	token string
}

type LiveDriver struct {
	base              *url.URL
	adminToken        string
	approverToken     string
	deniedToken       string
	metricSources     []metricEndpoint
	counterMetrics    map[string]string
	fixtures          LiveFixtures
	client            *http.Client
	agentScaler       AgentScaler
	isolationObserver IsolationObserver
	leaderFailover    leaderFailoverTarget
	eventStimulus     EventStimulus
	infrastructure    infrastructureQualificationOperator
	proofTimeout      time.Duration
	proofPoll         time.Duration
	noCallDwell       time.Duration
	scenarioMu        sync.Mutex
}

func NewLiveDriver(config LiveConfig) (*LiveDriver, error) {
	base, err := safeOperatorURL(config.AstronomerURL, config.AllowHTTP)
	if err != nil || strings.TrimSpace(config.AdminToken) == "" {
		return nil, errors.New("live driver requires a safe Astronomer URL and admin token")
	}
	metrics := make([]metricEndpoint, 0, len(config.MetricSources))
	seenMetricURLs := make(map[string]struct{}, len(config.MetricSources))
	for _, source := range config.MetricSources {
		parsed, parseErr := safeOperatorURL(source.URL, config.AllowHTTP)
		if parseErr != nil {
			return nil, fmt.Errorf("invalid metrics URL")
		}
		if _, duplicate := seenMetricURLs[parsed.String()]; duplicate {
			return nil, fmt.Errorf("duplicate metrics URL")
		}
		seenMetricURLs[parsed.String()] = struct{}{}
		metrics = append(metrics, metricEndpoint{url: parsed, token: strings.TrimSpace(source.Token)})
	}
	mapping := defaultCounterMetrics()
	for key, name := range config.CounterMetrics {
		if !metricNamePattern.MatchString(name) || (!contains(runtimeKeys, key) && !contains(downstreamKeys, key)) {
			return nil, fmt.Errorf("invalid counter metric mapping")
		}
		mapping[key] = name
	}
	client := config.HTTPClient
	if client == nil {
		client = &http.Client{
			Timeout:       30 * time.Second,
			Transport:     &http.Transport{TLSClientConfig: &tls.Config{MinVersion: tls.VersionTLS12}},
			CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
		}
	}
	proofTimeout, proofPoll, noCallDwell := config.ProofTimeout, config.ProofPoll, config.NoCallDwell
	if proofTimeout == 0 {
		proofTimeout = defaultProofTimeout
	}
	if proofPoll == 0 {
		proofPoll = defaultProofPoll
	}
	if noCallDwell == 0 {
		noCallDwell = defaultNoCallDwell
	}
	if proofTimeout < proofPoll || proofTimeout > 2*time.Minute || proofPoll < time.Millisecond || proofPoll > 10*time.Second || noCallDwell < time.Millisecond || noCallDwell > 2*time.Minute {
		return nil, errors.New("live proof timing is outside its safe bound")
	}
	var leaderFailover leaderFailoverTarget
	if config.LeaderFailover != nil {
		leaderFailover = config.LeaderFailover
	}
	var infrastructure infrastructureQualificationOperator
	if strings.TrimSpace(config.InfrastructureCommand) != "" {
		infrastructure, err = NewCommandInfrastructureOperator(config.InfrastructureCommand)
		if err != nil {
			return nil, err
		}
	}
	return &LiveDriver{
		base: base, adminToken: strings.TrimSpace(config.AdminToken), approverToken: strings.TrimSpace(config.ApproverToken), deniedToken: strings.TrimSpace(config.DeniedToken),
		metricSources: metrics, counterMetrics: mapping, fixtures: config.Fixtures,
		client: client, agentScaler: config.AgentScaler, isolationObserver: config.IsolationObserver, leaderFailover: leaderFailover, eventStimulus: config.EventStimulus, infrastructure: infrastructure,
		proofTimeout: proofTimeout, proofPoll: proofPoll, noCallDwell: noCallDwell,
	}, nil
}

func safeOperatorURL(raw string, allowHTTP bool) (*url.URL, error) {
	parsed, err := url.Parse(strings.TrimSpace(raw))
	httpLoopbackAllowed := allowHTTP && parsed.Scheme == "http" && netLoopback(parsed.Hostname())
	if err != nil || parsed.Hostname() == "" || parsed.User != nil || parsed.RawQuery != "" || parsed.Fragment != "" || (parsed.Scheme != "https" && !httpLoopbackAllowed) {
		return nil, errors.New("URL must use HTTPS without credentials, query, or fragment")
	}
	return parsed, nil
}

func netLoopback(host string) bool {
	ip := net.ParseIP(host)
	return ip != nil && ip.IsLoopback()
}

func defaultCounterMetrics() map[string]string {
	return map[string]string{
		"model_calls": "charlie_model_usage_total", "rag_queries": "charlie_rag_queries_total",
		"sessions": "charlie_sessions_created_total", "mcp_calls": "astronomer_charlie_mcp_calls_total",
		"tool_calls": "astronomer_charlie_actions_total", "work_claims": "charlie_agent_work_claims_total",
		"evidence_calls": "charlie_evidence_calls_total", "trigger_dispatches": "astronomer_charlie_trigger_events_total",
		"finding_dispatches": "charlie_findings_dispatched_total",
		"tunnel":             "astronomer_charlie_downstream_boundary_calls_total",
		"proxy":              "astronomer_charlie_downstream_boundary_calls_total",
		"kubernetes":         "astronomer_charlie_downstream_boundary_calls_total",
		"exec":               "astronomer_charlie_downstream_boundary_calls_total",
		"logs":               "astronomer_charlie_downstream_boundary_calls_total",
		"helm":               "astronomer_charlie_downstream_boundary_calls_total",
	}
}

func (d *LiveDriver) Counters(ctx context.Context) (CounterSet, error) {
	if len(d.metricSources) == 0 {
		return CounterSet{}, errors.New("metrics URLs are not configured")
	}
	samples := make([]metricSample, 0)
	for _, endpoint := range d.metricSources {
		request, _ := http.NewRequestWithContext(ctx, http.MethodGet, endpoint.url.String(), nil)
		request.Header.Set("Accept", "text/plain")
		if endpoint.token != "" {
			request.Header.Set("Authorization", "Bearer "+endpoint.token)
		}
		response, err := d.client.Do(request)
		if err != nil {
			return CounterSet{}, errors.New("metrics unavailable")
		}
		limited := &io.LimitedReader{R: response.Body, N: (16 << 20) + 1}
		parsed, parseErr := parsePrometheus(limited)
		_ = response.Body.Close()
		if response.StatusCode != http.StatusOK || parseErr != nil || limited.N == 0 {
			return CounterSet{}, errors.New("metrics invalid")
		}
		samples = append(samples, parsed...)
	}
	result := CounterSet{Runtime: map[string]uint64{}, Downstream: map[string]uint64{}}
	for _, key := range runtimeKeys {
		value, found := sumMetric(samples, d.counterMetrics[key], nil)
		if !found {
			return CounterSet{}, fmt.Errorf("required runtime counter %s is absent", key)
		}
		result.Runtime[key] = value
	}
	selectors := map[string]func(map[string]string) bool{
		"tunnel": func(v map[string]string) bool {
			return v["entrypoint"] == "tunnel_message" || v["entrypoint"] == "tunnel_broadcast" || v["entrypoint"] == "remote_dialer"
		},
		"proxy":      func(v map[string]string) bool { return v["entrypoint"] == "kubernetes_proxy" },
		"kubernetes": func(v map[string]string) bool { return v["operation"] == "kubernetes" },
		"exec":       func(v map[string]string) bool { return v["operation"] == "exec" },
		"logs":       func(v map[string]string) bool { return v["operation"] == "logs" },
		"helm":       func(v map[string]string) bool { return v["operation"] == "helm" },
	}
	for _, key := range downstreamKeys {
		metric := d.counterMetrics[key]
		value, found := sumMetric(samples, metric, selectors[key])
		if !found {
			// A newly started process may not have emitted a sample yet. The
			// metric family itself must still be present before zero is accepted.
			if !metricFamilyPresent(samples, metric) {
				return CounterSet{}, errors.New("downstream boundary metric is absent")
			}
		}
		result.Downstream[key] = value
	}
	return result, nil
}

func (d *LiveDriver) Run(ctx context.Context, request ScenarioRequest) ScenarioResult {
	// The public Hook already serializes scenario requests, but the driver is a
	// separately constructible type. Keep destructive mode transitions safe even
	// when a test harness or future caller invokes it directly.
	d.scenarioMu.Lock()
	defer d.scenarioMu.Unlock()
	switch request.Scenario {
	case "feature_false":
		return d.featureFalse(ctx, request.Scenario)
	case "unactivated":
		return d.unactivated(ctx, request)
	case "central_disabled":
		return d.centralDisabled(ctx, request.Scenario)
	case "emergency_disabled":
		return d.emergencyDisabled(ctx, request.Scenario)
	case "read_denial":
		return d.readDenial(ctx, request.Scenario)
	case "approval_expiry":
		return d.approvalExpiry(ctx, request.Scenario)
	case "approval_once":
		return d.approvalOnce(ctx, request.Scenario)
	case "approval_replay":
		return d.approvalReplay(ctx, request.Scenario)
	case "approval_reject":
		return d.approvalReject(ctx, request.Scenario)
	case "auto_allowlisted_success":
		return d.autoAllowlistedSuccess(ctx, request.Scenario)
	case "auto_nonallowlisted_approval":
		return d.autoNonallowlistedApproval(ctx, request.Scenario)
	case "versioned_rag_grounded":
		return d.versionedRAGGrounded(ctx, request.Scenario)
	case "general_answer":
		return d.generalAnswer(ctx, request.Scenario)
	case "discovery_mixed_catalog":
		return d.discoveryQualification(ctx, request.Scenario, "mixed_catalog")
	case "malformed_discovery":
		return d.discoveryQualification(ctx, request.Scenario, "malformed_catalog")
	case "diagnosis_alert", "approval_pending_alert", "approval_rejected_alert", "approval_expired_alert",
		"blocked_auto_alert", "failed_precondition_alert", "failed_verification_alert":
		return d.alertDeliveryQualification(ctx, request.Scenario)
	case "leader_kill_failover", "clean_install", "isolation_matrix", "resilience_matrix", "upgrade_rollback":
		if request.Scenario == "leader_kill_failover" && d.leaderFailover != nil {
			return d.leaderKillFailover(ctx, request)
		}
		return d.infrastructureQualification(ctx, request)
	default:
		return Unsupported(request.Scenario)
	}
}

